import openpyxl
wb=openpyxl.load_workbook('init.xlsx')
ws=wb['Sheet1']
words=[ws.cell(row=r,column=1).value for r in range(1,ws.max_row+1)]
pairs=[]
for i in range(len(words)):
    for j in range(i+1,len(words)):
        a=words[i].upper(); b=words[j].upper()
        if len(a)!=len(b): continue
        for v in 'AEIOU':
            if a.replace('S',v)==b:
                pairs.append((a,b)); break
seen=set(); uniq=[]
for p in pairs:
    if p not in seen:
        seen.add(p); uniq.append(p)
uniq.sort(key=lambda x:(x[0].lower(),x[1].lower()))
for idx,(a,b) in enumerate(uniq,1):
    ws.cell(row=idx,column=7).value=a
    ws.cell(row=idx,column=8).value=b
wb.save('output.xlsx')
print('saved',len(uniq))
